"""First-order problems in Lean, and step-by-step replay of E proof objects (roadmap W16).

E reports `Theorem` with a TSTP proof object. That is a prover claim. This module turns
it into a formal result only through the Lean kernel:

  * The statement is generated by Genesis from the parsed problem, never from the proof:
    `def stmt : Prop := ∀ (U : Type) (symbols …), ax₀ → … → axₖ → goal`. It is a
    trusted module.
  * The proof module is generated from E's proof object and is untrusted. Every inference
    of the refutation becomes its own lemma: the clause E derived, stated in Lean, proved
    from exactly the clauses E names as its parents by a fixed tactic cascade. Skolem
    constants introduced by E become existential witnesses, obtained from the negated
    goal. The main theorem assumes the negated goal, replays the steps in E's order and
    closes with E's empty clause.
  * `checker.accept` compiles both modules in the sandbox, binds the proof to the trusted
    statement, audits axioms and replays with leanchecker. Only then is the problem
    THEOREM_CHECKED.

A step that the cascade cannot close leaves the problem at E's PROVED (a prover claim);
the failure is recorded. Skolem functions with arguments (from ∀∃ shapes) are not
supported and are reported as such. Faithfulness of the statement translation is tested
separately: `decide` in Lean and the independent finite evaluator in `genesis.fol` must
agree on the same formula over the same finite tables (`truth_table_module`).
"""
import re
import time

from ..common import digest
from ..fol import ParseError, free_vars, parse, signature

STEP_TACTIC = ('first\n'
               '    | grind\n'
               '    | (intros; simp_all)\n'
               '    | (intros; simp only [Classical.not_forall, not_imp, not_and, not_or, ne_eq] at *; grind)')
SKOLEM = re.compile(r'^esk\d+_(\d+)$')


def sym(name):
    return 's_' + name


def var(name):
    return 'v_' + name


def term(t):
    if t[0] == 'var':
        return var(t[1])
    if not t[2]:
        return sym(t[1])
    return '(' + ' '.join([sym(t[1])] + [term(a) for a in t[2]]) + ')'


def formula(f):
    k = f[0]
    if k == 'const':
        return 'True' if f[1] else 'False'
    if k == 'eq':
        return f'({term(f[1])} = {term(f[2])})'
    if k == 'pred':
        return '(' + ' '.join([sym(f[1])] + [term(a) for a in f[2]]) + ')' if f[2] else sym(f[1])
    if k == 'not':
        return f'(¬ {formula(f[1])})'
    ops = {'and': '∧', 'or': '∨', 'imp': '→', 'iff': '↔'}
    if k in ops:
        return f'({formula(f[1])} {ops[k]} {formula(f[2])})'
    if k in ('all', 'ex'):
        q = '∀' if k == 'all' else '∃'
        return f'({q} {var(f[1])} : U, {formula(f[2])})'
    raise ValueError(f'unknown node {k}')


def _order(f, out):
    """Free variables in order of first appearance."""
    k = f[0]
    if k == 'var':
        if f[1] not in out:
            out.append(f[1])
    elif k == 'fn' or k == 'pred':
        for a in f[2]:
            _order(a, out)
    elif k == 'eq':
        _order(f[1], out); _order(f[2], out)
    elif k == 'not':
        _order(f[1], out)
    elif k in ('and', 'or', 'imp', 'iff'):
        _order(f[1], out); _order(f[2], out)
    return out


def closure(f):
    """Universal closure of a clause (cnf variables are implicitly universal)."""
    vs = [v for v in _order(f, []) if v in free_vars(f)]
    body = formula(f)
    return f'(∀ {" ".join(var(v) for v in vs)} : U, {body})' if vs else body


def binders(sig):
    out = ['(U : Type) [Nonempty U]']
    for name, arity in sorted(sig['functions'].items()):
        out.append(f'({sym(name)} : {" → ".join(["U"] * (arity + 1))})')
    for name, arity in sorted(sig['predicates'].items()):
        out.append(f'({sym(name)} : {" → ".join(["U"] * arity + ["Prop"])})')
    return out


def binder_names(sig):
    return ['U'] + [sym(n) for n in sorted(sig['functions'])] + [sym(n) for n in sorted(sig['predicates'])]


def module_names(problem_id):
    h = digest({'p': problem_id})[:10].upper()
    return f'FOFS{h}', f'FOFP{h}'


def statement_module(problem_id, axioms, goal):
    """Trusted: the problem as one closed Lean proposition."""
    sig = signature(axioms + [goal])
    stmt, _ = module_names(problem_id)
    hyps = ' → '.join([formula(a) for a in axioms] + [formula(goal)])
    source = (f'namespace {stmt}\n\n'
              f'/-- Problem {problem_id}, generated by Genesis from the parsed FOF problem. -/\n'
              f'def stmt : Prop :=\n  ∀ {" ".join(binders(sig))},\n    {hyps}\n\nend {stmt}\n')
    return {'name': stmt, 'source': source, 'trusted': True}, f'{stmt}.stmt', sig


# ---------------------------------------------------------------- TSTP proof objects

def _split_top(text):
    parts, depth, cur, quote = [], 0, [], False
    for ch in text:
        if ch == "'" and depth >= 0:
            quote = not quote
        if not quote:
            if ch in '([':
                depth += 1
            elif ch in ')]':
                depth -= 1
            elif ch == ',' and depth == 0:
                parts.append(''.join(cur).strip()); cur = []
                continue
        cur.append(ch)
    parts.append(''.join(cur).strip())
    return parts


def tstp_steps(proof_text):
    """Annotated formulas of a TSTP proof, in order: name, language, role, formula AST,
    parents (names of earlier formulas or inputs), rules and statuses."""
    items, buf = [], ''
    for line in proof_text.splitlines():
        s = line.strip()
        if not buf and not (s.startswith('fof(') or s.startswith('cnf(')):
            continue
        buf += s
        if buf.endswith(').'):
            items.append(buf); buf = ''
    steps, names = [], set()
    for item in items:
        lang = item[:3]
        parts = _split_top(item[4:-2])
        name, role, text, source = parts[0], parts[1], parts[2], parts[3] if len(parts) > 3 else ''
        f = parse(text)
        tokens = re.findall(r'[A-Za-z_][A-Za-z0-9_]*', source)
        rules = sorted(set(re.findall(r'inference\((\w+)', source)))
        statuses = sorted(set(re.findall(r'status\((\w+)\)', source)))
        parents = []
        if source.startswith('file('):
            parents = []
        else:
            for tok in tokens:
                if tok in names and tok not in parents:
                    parents.append(tok)
        steps.append({'name': name, 'lang': lang, 'role': role, 'formula': f, 'text': text, 'parents': parents,
                      'rules': rules, 'statuses': statuses, 'input': source.startswith('file(')})
        names.add(name)
    return steps


def _skolems(f, out=None):
    out = {} if out is None else out
    k = f[0]
    if k == 'fn':
        if SKOLEM.match(f[1]):
            out[f[1]] = len(f[2])
        for a in f[2]:
            _skolems(a, out)
    elif k == 'pred':
        for a in f[2]:
            _skolems(a, out)
    elif k == 'eq':
        _skolems(f[1], out); _skolems(f[2], out)
    elif k == 'not':
        _skolems(f[1], out)
    elif k in ('and', 'or', 'imp', 'iff'):
        _skolems(f[1], out); _skolems(f[2], out)
    elif k in ('all', 'ex'):
        _skolems(f[2], out)
    return out


# ---------------------------------------------------------------- ground instance hints
#
# Lean's `grind` instantiates universally quantified facts by E-matching. A superposition
# step often needs an instance whose matching term is not yet in the e-graph (the classic
# case is a variable-only side, X = mul(X, e)). Each step therefore gets ground instances
# of its parents, found here by bounded instantiation over the step's own ground terms and
# confirmed unsatisfiable (against the negated conclusion) by a small congruence closure
# with case splits. The instances are only hints: Lean re-checks everything, and a wrong
# or missing hint just leaves the step to the plain cascade.

TRUE = ('fn', '$T', ())


def _prefix(f):
    vs = []
    while f[0] == 'all':
        vs.append(f[1]); f = f[2]
    return vs, f


def _clause(f):
    """Literals (positive?, s, t) of a quantifier-free disjunction, or None."""
    lits = []

    def walk(g):
        k = g[0]
        if k == 'or':
            return walk(g[1]) and walk(g[2])
        if k == 'const':
            return True if not g[1] else None
        neg = k == 'not'
        a = g[1] if neg else g
        if a[0] == 'eq':
            lits.append((not neg, a[1], a[2])); return True
        if a[0] == 'pred':
            lits.append((not neg, ('fn', 'P:' + a[1], a[2]), TRUE)); return True
        return False
    if f == ('const', False):
        return []
    if walk(f) is not True:
        return None
    return lits


def _cnf(body):
    """Clauses of a conjunction of quantifier-free disjunctions, or None."""
    if body[0] == 'and':
        a, b = _cnf(body[1]), _cnf(body[2])
        return None if a is None or b is None else a + b
    c = _clause(body)
    return None if c is None else [c]


def _shape(st_formula, lang):
    """(variable order, clauses) for an instantiable parent or conclusion, or None."""
    if lang == 'cnf':
        vs = [v for v in _order(st_formula, []) if v in free_vars(st_formula)]
        body = st_formula
    else:
        vs, body = _prefix(st_formula)
    cs = _cnf(body)
    return (vs, cs) if cs is not None else None


def _subst(t, s):
    if t[0] == 'var':
        return s.get(t[1], t)
    return ('fn', t[1], tuple(_subst(a, s) for a in t[2]))


def _terms(t, out):
    if t[0] == 'fn':
        if not t[1].startswith('P:') and t != TRUE:
            out.add(t)
        for a in t[2]:
            _terms(a, out)
    return out


def _nonvar_subterms(t, out):
    if t[0] == 'fn':
        if any(x[0] == 'var' for x in _all(t)):
            out.append(t)
        for a in t[2]:
            _nonvar_subterms(a, out)
    return out


def _all(t):
    yield t
    if t[0] == 'fn':
        for a in t[2]:
            yield from _all(a)


def _match(p, t, s):
    if p[0] == 'var':
        if p[1] in s:
            return s if s[p[1]] == t else None
        return {**s, p[1]: t}
    if t[0] != 'fn' or p[1] != t[1] or len(p[2]) != len(t[2]):
        return None
    for a, b in zip(p[2], t[2]):
        s = _match(a, b, s)
        if s is None:
            return None
    return s


def _size(t):
    return 1 if t[0] == 'var' else 1 + sum(_size(a) for a in t[2])


class _CC:
    """Congruence closure over ground terms (union-find with use lists and a signature
    table, processing merges incrementally)."""

    def __init__(self):
        self.ids, self.app, self.up, self.uses, self.sig, self.pending = {}, [], [], [], {}, []

    def find(self, i):
        while self.up[i] != i:
            self.up[i] = self.up[self.up[i]]; i = self.up[i]
        return i

    def _key(self, i):
        name, args = self.app[i]
        return name, tuple(self.find(a) for a in args)

    def add(self, t):
        if t in self.ids:
            return self.ids[t]
        args = [self.add(a) for a in t[2]]
        i = len(self.app)
        self.ids[t] = i; self.app.append((t[1], args)); self.up.append(i); self.uses.append([])
        if args:
            key = self._key(i)
            if key in self.sig:
                self.pending.append((i, self.sig[key]))
            else:
                self.sig[key] = i
            for a in {self.find(a) for a in args}:
                self.uses[a].append(i)
            self._process()
        return i

    def merge(self, s, t):
        self.pending.append((self.add(s), self.add(t)))
        self._process()

    def _process(self):
        while self.pending:
            a, b = self.pending.pop()
            ra, rb = self.find(a), self.find(b)
            if ra == rb:
                continue
            if len(self.uses[ra]) > len(self.uses[rb]):
                ra, rb = rb, ra
            self.up[ra] = rb
            for u in self.uses[ra]:
                key = self._key(u)
                other = self.sig.get(key)
                if other is None:
                    self.sig[key] = u
                elif self.find(other) != self.find(u):
                    self.pending.append((u, other))
                self.uses[rb].append(u)
            self.uses[ra] = []

    def eq(self, s, t):
        return self.find(self.add(s)) == self.find(self.add(t))


def _unsat(clauses, depth=0):
    """Ground clause set (lists of literals) unsatisfiable? False also means 'unknown'."""
    if any(len(c) == 0 for c in clauses):
        return True
    units = [c[0] for c in clauses if len(c) == 1]
    rest = [c for c in clauses if len(c) > 1]
    cc = _CC()
    done = set()
    while True:
        for u in units:
            if u not in done and u[0]:
                cc.merge(u[1], u[2])
            done.add(u)
        if any(not pos and cc.eq(a, b) for pos, a, b in units):
            return True
        nxt, new_units = [], []
        for c in rest:
            live = [l for l in c if not (not l[0] and cc.eq(l[1], l[2]))]
            if any(l[0] and cc.eq(l[1], l[2]) for l in live):
                continue
            if not live:
                return True
            if len(live) == 1:
                new_units.append(live[0])
            else:
                nxt.append(live)
        new_units = [u for u in new_units if u not in done]
        rest = nxt
        if new_units:
            units = units + new_units
            continue
        if not rest or depth >= 4:
            return False
        c = rest[0]
        base = [[u] for u in units] + rest[1:]
        return all(_unsat(base + [[l]], depth + 1) for l in c)


def _minimise(keys, test):
    """A smaller subset of `keys` that still passes `test` (chunked deletion)."""
    keep, chunk = list(keys), max(1, len(keys) // 2)
    while chunk >= 1:
        i, changed = 0, False
        while i < len(keep):
            trial = keep[:i] + keep[i + chunk:]
            if test(trial):
                keep, changed = trial, True
            else:
                i += chunk
        if chunk == 1:
            break
        chunk = max(1, chunk // 2)
    return keep


def _walk(t, s):
    while t[0] == 'var' and t[1] in s:
        t = s[t[1]]
    return t


def _occurs(v, t, s):
    t = _walk(t, s)
    if t[0] == 'var':
        return t[1] == v
    return any(_occurs(v, a, s) for a in t[2])


def _unify(a, b, s):
    a, b = _walk(a, s), _walk(b, s)
    if a == b:
        return s
    if a[0] == 'var':
        return None if _occurs(a[1], b, s) else {**s, a[1]: b}
    if b[0] == 'var':
        return None if _occurs(b[1], a, s) else {**s, b[1]: a}
    if a[1] != b[1] or len(a[2]) != len(b[2]):
        return None
    for x, y in zip(a[2], b[2]):
        s = _unify(x, y, s)
        if s is None:
            return None
    return s


def _resolve(t, s):
    t = _walk(t, s)
    if t[0] == 'var':
        return t
    return ('fn', t[1], tuple(_resolve(a, s) for a in t[2]))


def _rename_vars(t, tag):
    if t[0] == 'var':
        return ('var', t[1] + tag)
    return ('fn', t[1], tuple(_rename_vars(a, tag) for a in t[2]))


def _vars_of(t, out):
    if t[0] == 'var':
        out.add(t[1])
    else:
        for a in t[2]:
            _vars_of(a, out)
    return out


def _overlaps(parents):
    """Superposition overlaps between parents: for a positive equation side l of one parent
    and a non-variable subterm u of another (or the same, renamed apart), the most general
    unifier. Returns ([{parent index: {variable: term with variables}}], [(overlap index,
    result sides)]): the result sides are B's literal after the rewrite, under the unifier."""
    out, results = [], []
    for i, A in enumerate(parents):
        if not A:
            continue
        for j, B in enumerate(parents):
            if not B:
                continue
            ta, tb = '@a', '@b'
            for ca in A[1]:
                for pos, l, r in ca:
                    if not pos:
                        continue
                    for lhs in (l, r):
                        if lhs[0] == 'var':
                            continue
                        lhs_r = _rename_vars(lhs, ta)
                        for cb in B[1]:
                            for _, x, y in cb:
                                for side in (x, y):
                                    for u in _nonvar_subterms(side, []) + ([side] if side[0] == 'fn' and
                                                                           not _vars_of(side, set()) else []):
                                        sg = _unify(lhs_r, _rename_vars(u, tb), {})
                                        if sg is None:
                                            continue
                                        rhs = r if lhs is l else l
                                        res = [(_resolve(_replace(_rename_vars(z, tb), _rename_vars(u, tb),
                                                                  _rename_vars(rhs, ta)), sg))
                                               for z in (x, y)]
                                        results.append((len(out), tuple(res)))
                                        out.append({i: {v: _resolve(('var', v + ta), sg) for v in A[0]},
                                                    j: {**({v: _resolve(('var', v + ta), sg) for v in A[0]}
                                                           if i == j else {}),
                                                        **{v: _resolve(('var', v + tb), sg) for v in B[0]}}}
                                                   if i != j else
                                                   {i: {v: _resolve(('var', v + ta), sg) for v in A[0]},
                                                    -1 - j: {v: _resolve(('var', v + tb), sg) for v in B[0]}})
    return out, results


def _replace(t, old, new):
    if t == old:
        return new
    if t[0] == 'var':
        return t
    return ('fn', t[1], tuple(_replace(a, old, new) for a in t[2]))


def _rules(parents, exclude=()):
    """Unit positive equations among the parents, oriented as size-decreasing rewrite
    rules (E rewrites with its term ordering, which under unit weights never increases
    size): [(parent index, lhs, rhs)]."""
    out = []
    for i, P in enumerate(parents):
        if i in exclude or not P or len(P[1]) != 1 or len(P[1][0]) != 1 or not P[1][0][0][0]:
            continue
        _, l, r = P[1][0][0]
        for a, b in ((l, r), (r, l)):
            if a[0] != 'var' and _size(a) > _size(b) and _vars_of(b, set()) <= _vars_of(a, set()):
                out.append((i, a, b))
    return out


def _commutative(parents):
    """{symbol: (parent index, first variable, second variable)} for parents that are a
    commutativity law f(V1,V2) = f(V2,V1)."""
    out = {}
    for i, P in enumerate(parents):
        if not P or len(P[1]) != 1 or len(P[1][0]) != 1 or not P[1][0][0][0]:
            continue
        _, l, r = P[1][0][0]
        if (l[0] == r[0] == 'fn' and l[1] == r[1] and len(l[2]) == 2 and all(a[0] == 'var' for a in l[2])
                and l[2][0] != l[2][1] and r[2] == (l[2][1], l[2][0])):
            out.setdefault(l[1], (i, l[2][0][1], l[2][1][1]))
    return out


def _match_c(p, t, s, comm, swaps=()):
    """Matches of pattern p against t modulo commutativity of the symbols in `comm`
    (B21): yields (substitution, the subterms of t whose arguments were swapped)."""
    if p[0] == 'var':
        if p[1] in s:
            if s[p[1]] == t:
                yield s, swaps
            return
        yield {**s, p[1]: t}, swaps
        return
    if t[0] != 'fn' or p[1] != t[1] or len(p[2]) != len(t[2]):
        return
    orders = [(t[2], swaps)]
    if p[1] in comm and len(t[2]) == 2 and t[2][0] != t[2][1]:
        orders.append(((t[2][1], t[2][0]), swaps + (t,)))
    for args, sw in orders:
        yield from _match_args(p[2], args, s, comm, sw)


def _match_args(ps, ts, s, comm, swaps):
    if not ps:
        yield s, swaps
        return
    for s1, sw1 in _match_c(ps[0], ts[0], s, comm, swaps):
        yield from _match_args(ps[1:], ts[1:], s1, comm, sw1)


def _swap_instances(swaps, comm):
    """Commutativity instances that justify the swapped subterms: [(parent index, substitution)]."""
    out = []
    for u in swaps:
        i, v1, v2 = comm[u[1]]
        out.append((i, {v1: u[2][0], v2: u[2][1]}))
    return out


def _rewrite_once(t, rules, comm=None):
    """One leftmost-outermost rewrite step, matching modulo commutativity when `comm` is
    given: (new term, [(parent index, substitution)] for the rule and any swaps)."""
    for i, l, r in rules:
        m = next(_match_c(l, t, {}, comm or {}), None)
        if m is not None:
            return _subst(r, m[0]), [(i, m[0])] + _swap_instances(m[1], comm or {})
    if t[0] == 'fn':
        for k, a in enumerate(t[2]):
            s = _rewrite_once(a, rules, comm)
            if s is not None:
                args = list(t[2])
                args[k] = s[0]
                return ('fn', t[1], tuple(args)), s[1]
    return None


def _ground_all(t, g):
    if t[0] == 'var':
        return g
    return ('fn', t[1], tuple(_ground_all(a, g) for a in t[2]))


def _rewrite_path(sides, rules, comm=None, steps=12):
    """Every state on the way to a normal form of an equation's sides under `rules`, with
    the rule instances used so far: [((side, side), [(parent index, substitution)])]."""
    out, used, cur = [], [], list(sides)
    for _ in range(steps):
        for k in (0, 1):
            s = _rewrite_once(cur[k], rules, comm)
            if s is not None:
                cur[k] = s[0]
                used = used + s[1]
                out.append((tuple(cur), used))
                break
        else:
            break
    return out


def _overlaps_v1(parents):
    """Superposition overlaps between parents: for a positive equation side l of one parent
    and a non-variable subterm u of another (or the same, renamed apart), the most general
    unifier. Yields {parent index: {variable: term with variables}} pairs."""
    out = []
    for i, A in enumerate(parents):
        if not A:
            continue
        for j, B in enumerate(parents):
            if not B:
                continue
            ta, tb = '@a', '@b'
            for ca in A[1]:
                for pos, l, r in ca:
                    if not pos:
                        continue
                    for lhs in (l, r):
                        if lhs[0] == 'var':
                            continue
                        lhs_r = _rename_vars(lhs, ta)
                        for cb in B[1]:
                            for _, x, y in cb:
                                for side in (x, y):
                                    for u in _nonvar_subterms(side, []) + ([side] if side[0] == 'fn' and
                                                                           not _vars_of(side, set()) else []):
                                        sg = _unify(lhs_r, _rename_vars(u, tb), {})
                                        if sg is None:
                                            continue
                                        out.append({i: {v: _resolve(('var', v + ta), sg) for v in A[0]},
                                                    j: {**({v: _resolve(('var', v + ta), sg) for v in A[0]}
                                                           if i == j else {}),
                                                        **{v: _resolve(('var', v + tb), sg) for v in B[0]}}}
                                                   if i != j else
                                                   {i: {v: _resolve(('var', v + ta), sg) for v in A[0]},
                                                    -1 - j: {v: _resolve(('var', v + tb), sg) for v in B[0]}})
    return out


def _ground_hints_v1(parents, conclusion, constants, *, rounds=3, cap=1500, max_terms=250, seconds=1.5):
    """parents: [(variable order, clauses)] (None for a parent that cannot be instantiated);
    conclusion: (variable order, [one clause]). Returns [(parent index, [terms in order])]
    whose instances, with the ground parents and the negated conclusion, are
    unsatisfiable, [] if no instance is needed, or None when none were found in budget."""
    deadline = time.monotonic() + seconds
    cvars, ccl = conclusion
    if len(ccl) != 1:
        return None
    sk = {v: ('fn', '#' + v, ()) for v in cvars}
    neg = [[(not pos, _subst(a, sk), _subst(b, sk))] for pos, a, b in ccl[0]]
    ground = [c for sh in parents if sh and not sh[0] for c in sh[1]]
    sides = [x for sh in parents if sh for c in sh[1] for _, a, b in c for x in (a, b)] + \
            [x for c in neg for _, a, b in c for x in (a, b)]
    limit = 2 * max(_size(x) for x in sides) + 2 if sides else 16
    T = set(constants)
    for c in neg + ground:
        for _, a, b in c:
            _terms(a, T); _terms(b, T)
    if _unsat(neg + ground):
        return []

    def clauses(keys):
        out = list(neg + ground)
        for i, args in keys:
            m = dict(zip(parents[i][0], args))
            out += [[(q, _subst(a, m), _subst(b, m)) for q, a, b in c] for c in parents[i][1]]
        return out
    inst, seen = [], set()
    # round 0: instances from superposition overlaps, free variables grounded over T
    terms = sorted(T, key=lambda t: (_size(t), repr(t)))[:max_terms]
    seeded = []
    for ov in _overlaps_v1(parents):
        free = sorted({x for m in ov.values() for t in m.values() for x in _vars_of(t, set())})
        combos = [{}]
        for v in free:
            if len(combos) * len(terms) > 300:
                combos = []
                break
            combos = [{**c, v: t} for c in combos for t in terms]
        for c in combos:
            for idx, m in ov.items():
                i = idx if idx >= 0 else -1 - idx
                key = (i, tuple(_subst(m[v], c) for v in parents[i][0]))
                if key not in seen:
                    seen.add(key); seeded.append(key)
        if len(seeded) > cap or time.monotonic() > deadline:
            break
    if seeded:
        inst += seeded
        for i, args in seeded:
            m = dict(zip(parents[i][0], args))
            for c in parents[i][1]:
                for _, a, b in c:
                    _terms(_subst(a, m), T); _terms(_subst(b, m), T)
        if _unsat(clauses(inst)):
            return _minimise(inst, lambda ks: time.monotonic() < deadline + 2 and _unsat(clauses(ks)))
    for _ in range(rounds):
        added = []
        terms = sorted(T, key=lambda t: (_size(t), repr(t)))[:max_terms]
        for i, sh in enumerate(parents):
            if not sh or not sh[0]:
                continue
            vs, cls = sh
            pats = []
            for c in cls:
                for _, a, b in c:
                    _nonvar_subterms(a, pats); _nonvar_subterms(b, pats)
            subs = []
            for pat in pats:
                for t in terms:
                    m = _match(pat, t, {})
                    if m is not None:
                        subs.append(m)
            if len(vs) == 1:
                subs += [{vs[0]: t} for t in terms]
            for m in subs:
                combos = [m]
                for v in [v for v in vs if v not in m]:
                    if len(combos) * len(terms) > 200:
                        combos = []
                        break
                    combos = [{**c, v: t} for c in combos for t in terms]
                for c in combos:
                    key = (i, tuple(c[v] for v in vs))
                    if key in seen:
                        continue
                    seen.add(key)
                    inst_sides = [_subst(x, c) for cl in cls for _, a, b in cl for x in (a, b)]
                    if max(_size(x) for x in inst_sides) <= limit:
                        added.append(key)
                if len(added) > cap or time.monotonic() > deadline:
                    break
            if len(added) > cap or time.monotonic() > deadline:
                break
        if not added:
            break
        inst += added
        for i, args in added:
            m = dict(zip(parents[i][0], args))
            for c in parents[i][1]:
                for _, a, b in c:
                    _terms(_subst(a, m), T); _terms(_subst(b, m), T)
        if time.monotonic() > deadline:
            return None
        if _unsat(clauses(inst)):
            return _minimise(inst, lambda ks: time.monotonic() < deadline + 2 and _unsat(clauses(ks)))
    return None


# Ground-hint generator versions (B20_R25). v1 is the generator as it ran up to B20_R24, kept
# verbatim so earlier replays stay reproducible. v2 (ported from the B21 side branch) also
# matches each superposition result to the conclusion, rewrites it towards a normal form under
# the other parents first (size-decreasing rules, matching modulo a commutativity parent: E's
# `rw` after `spm`, often by a derived commutativity law), hands the rule and commutativity
# instances to Lean, and seeds matched overlaps before blind enumeration. Hints are only
# instances given to Lean, which checks every step: a wrong hint can make a step fail, never
# make a false step pass.
HINT_VERSIONS = ('v1', 'v2')
HINTS = 'v2'


def ground_hints(parents, conclusion, constants, *, version=None, **kw):
    """parents: [(variable order, clauses)] (None for a parent that cannot be instantiated);
    conclusion: (variable order, [one clause]). Returns [(parent index, [terms in order])]
    whose instances, with the ground parents and the negated conclusion, are
    unsatisfiable, [] if no instance is needed, or None when none were found in budget.
    `version` (default: the module's HINTS) selects the generator."""
    version = version or HINTS
    if version not in HINT_VERSIONS:
        raise ValueError(f'unknown ground-hint version {version!r}')
    return (_ground_hints_v1 if version == 'v1' else _ground_hints_v2)(parents, conclusion, constants, **kw)


def _ground_hints_v2(parents, conclusion, constants, *, rounds=3, cap=1500, max_terms=250, seconds=1.5):
    """parents: [(variable order, clauses)] (None for a parent that cannot be instantiated);
    conclusion: (variable order, [one clause]). Returns [(parent index, [terms in order])]
    whose instances, with the ground parents and the negated conclusion, are
    unsatisfiable, [] if no instance is needed, or None when none were found in budget."""
    deadline = time.monotonic() + seconds
    cvars, ccl = conclusion
    if len(ccl) != 1:
        return None
    sk = {v: ('fn', '#' + v, ()) for v in cvars}
    neg = [[(not pos, _subst(a, sk), _subst(b, sk))] for pos, a, b in ccl[0]]
    ground = [c for sh in parents if sh and not sh[0] for c in sh[1]]
    sides = [x for sh in parents if sh for c in sh[1] for _, a, b in c for x in (a, b)] + \
            [x for c in neg for _, a, b in c for x in (a, b)]
    limit = 2 * max(_size(x) for x in sides) + 2 if sides else 16
    T = set(constants)
    for c in neg + ground:
        for _, a, b in c:
            _terms(a, T); _terms(b, T)
    if _unsat(neg + ground):
        return []

    def clauses(keys):
        out = list(neg + ground)
        for i, args in keys:
            m = dict(zip(parents[i][0], args))
            out += [[(q, _subst(a, m), _subst(b, m)) for q, a, b in c] for c in parents[i][1]]
        return out
    inst, seen = [], set()
    # round 0: instances from superposition overlaps, free variables grounded over T
    terms = sorted(T, key=lambda t: (_size(t), repr(t)))[:max_terms]
    seeded = []
    overlaps, results = _overlaps(parents)
    goal_sides = [(a, b) for c in neg for _, a, b in c]
    by_overlap = {}
    all_rules = _rules(parents)
    comm = _commutative(parents)
    for k, (s1, s2) in results:
        # the overlap result, and (B21) the states on its way to a normal form under the
        # other parents (E's `rw` after `spm`), matched to the conclusion; with a
        # commutativity parent, rewriting and matching work modulo commutativity
        cands = [((s1, s2), [])]
        if all_rules and time.monotonic() < deadline:
            own = {i if i >= 0 else -1 - i for i in overlaps[k]}
            for rules in (_rules(parents, exclude=own), all_rules):
                cands += _rewrite_path((s1, s2), rules)
                if comm:
                    cands += _rewrite_path((s1, s2), rules, comm)
        for (r1, r2), extra in cands:
            for a, b in goal_sides:
                for x, y in ((a, b), (b, a)):
                    found = 0
                    for m1, sw1 in _match_c(r1, x, {}, comm):
                        for m, sw in _match_c(r2, y, m1, comm, sw1):
                            by_overlap.setdefault(k, []).append((m, extra + _swap_instances(sw, comm)))
                            found += 1
                            break
                        if found >= 2:
                            break
    def seed(ks):
        out = []
        for k in ks:
            ov = overlaps[k]
            free = sorted({x for m in ov.values() for t in m.values() for x in _vars_of(t, set())})
            # variables the result does not mention are arbitrary: any ground term will do
            combos = [({**{v: terms[0] for v in free if v not in c}, **c}, extra)
                      for c, extra in by_overlap.get(k, [])] if terms else []
            if not combos:
                combos = [{}]
                for v in free:
                    if len(combos) * len(terms) > 300:
                        combos = []
                        break
                    combos = [{**c, v: t} for c in combos for t in terms]
                combos = [(c, []) for c in combos]
            for c, extra in combos:
                keys = []
                for idx, m in ov.items():
                    i = idx if idx >= 0 else -1 - idx
                    keys.append((i, tuple(_subst(m[v], c) for v in parents[i][0])))
                for i, rm in extra:                # the rewrite-rule instances, grounded alike
                    keys.append((i, tuple(_ground_all(_subst(rm.get(v, terms[0]), c), terms[0])
                                          for v in parents[i][0])))
                for key in keys:
                    if key not in seen:
                        seen.add(key); out.append(key)
            if len(out) > cap or time.monotonic() > deadline:
                break
        return out
    # overlaps whose result matched the conclusion first (B21): enumerating the others
    # can exhaust the cap before a matched one is reached
    matched = [k for k in range(len(overlaps)) if k in by_overlap]
    first = seed(matched)
    if first and _unsat(clauses(first)):
        return _minimise(first, lambda ks: time.monotonic() < deadline + 2 and _unsat(clauses(ks)))
    seeded = first + seed([k for k in range(len(overlaps)) if k not in by_overlap])
    if seeded:
        inst += seeded
        for i, args in seeded:
            m = dict(zip(parents[i][0], args))
            for c in parents[i][1]:
                for _, a, b in c:
                    _terms(_subst(a, m), T); _terms(_subst(b, m), T)
        if _unsat(clauses(inst)):
            return _minimise(inst, lambda ks: time.monotonic() < deadline + 2 and _unsat(clauses(ks)))
    for _ in range(rounds):
        added = []
        terms = sorted(T, key=lambda t: (_size(t), repr(t)))[:max_terms]
        for i, sh in enumerate(parents):
            if not sh or not sh[0]:
                continue
            vs, cls = sh
            pats = []
            for c in cls:
                for _, a, b in c:
                    _nonvar_subterms(a, pats); _nonvar_subterms(b, pats)
            subs = []
            for pat in pats:
                for t in terms:
                    m = _match(pat, t, {})
                    if m is not None:
                        subs.append(m)
            if len(vs) == 1:
                subs += [{vs[0]: t} for t in terms]
            for m in subs:
                combos = [m]
                for v in [v for v in vs if v not in m]:
                    if len(combos) * len(terms) > 200:
                        combos = []
                        break
                    combos = [{**c, v: t} for c in combos for t in terms]
                for c in combos:
                    key = (i, tuple(c[v] for v in vs))
                    if key in seen:
                        continue
                    seen.add(key)
                    inst_sides = [_subst(x, c) for cl in cls for _, a, b in cl for x in (a, b)]
                    if max(_size(x) for x in inst_sides) <= limit:
                        added.append(key)
                if len(added) > cap or time.monotonic() > deadline:
                    break
            if len(added) > cap or time.monotonic() > deadline:
                break
        if not added:
            break
        inst += added
        for i, args in added:
            m = dict(zip(parents[i][0], args))
            for c in parents[i][1]:
                for _, a, b in c:
                    _terms(_subst(a, m), T); _terms(_subst(b, m), T)
        if time.monotonic() > deadline:
            return None
        if _unsat(clauses(inst)):
            return _minimise(inst, lambda ks: time.monotonic() < deadline + 2 and _unsat(clauses(ks)))
    return None


def _render(t):
    if t[0] == 'var':
        return var(t[1])
    head = var(t[1][1:]) if t[1].startswith('#') else sym(t[1])
    return '(' + ' '.join([head] + [_render(a) for a in t[2]]) + ')' if t[2] else head


def refutation_block(prefix, sig, hyps, target, proof_text, positions=None):
    """Lean text for one E refutation: a lemma per inference, then
    `{prefix}_thm : ∀ binders, hyp₀ → … → target`. E's input names are ax0 … for `hyps` in
    order and `goal` for `target`; `positions` gives other E input indices for the hyps
    when only some of E's inputs are passed (B20: the inputs a proof actually uses).
    Returns (text | None, reason, step table)."""
    try:
        steps = tstp_steps(proof_text)
    except ParseError as exc:
        return None, f'proof object does not parse: {exc}', []
    positions = list(range(len(hyps))) if positions is None else list(positions)
    if len(positions) != len(hyps) or len(set(positions)) != len(positions):
        return None, 'input positions do not match the hypotheses', []
    inputs = {f'ax{i}': a for i, a in zip(positions, hyps)}
    statement, sk_of, shape, statement_ast = {}, {}, {'goal': None}, {}
    lemmas, main, table = [], [], []
    hyp_of = {f'ax{i}': f'ax{i}' for i in positions}
    hyp_of['goal'] = 'hgoal'
    sk_scope = {}
    for st in steps:
        n = st['name']
        if st['input']:
            if n in inputs:
                statement[n] = formula(inputs[n])
                shape[n] = _shape(inputs[n], 'fof')
                statement_ast[n] = inputs[n]
            elif n == 'goal':
                statement[n] = formula(target)
                statement['hgoal'] = f'(¬ {formula(target)})'
            else:
                return None, f'unknown input {n!r}', table
            sk_of[n] = {}
            continue
        f = st['formula']
        prop = closure(f) if st['lang'] == 'cnf' else formula(f)
        sks = _skolems(f)
        bad = [k for k, a in sks.items() if a > 0]
        if bad:
            return None, f'skolem functions with arguments are not supported ({bad})', table
        parents = st['parents']
        if not parents:
            return None, f'step {n} names no parents', table
        new = sorted(k for k in sks if k not in sk_scope)
        hyp_props = [statement['hgoal'] if q == 'goal' else statement[q] for q in parents]
        used_scope = sorted(set(k for q in parents for k in sk_of.get(q, {})) | (set(sks) - set(new)))
        args = binders(sig) + [f'({sym(k)} : U)' for k in used_scope]
        hs = [f'(h{i} : {h})' for i, h in enumerate(hyp_props)]
        lname = f'{prefix}_step_' + re.sub(r'\W', '_', n)
        concl = f'∃ {" ".join(sym(k) for k in new)} : U, {prop}' if new else prop
        tactic = STEP_TACTIC
        mine = _shape(f, st['lang'])
        consts = [('fn', c, ()) for c, a in sig['functions'].items() if a == 0] + \
                 [('fn', c, ()) for c in used_scope]
        hinted = False
        if new:
            ws = [f'w{j}' for j in range(len(new))]
            alts = []
            for order in ([ws, list(reversed(ws))] if len(ws) > 1 else [ws]):
                alts.append('(simp only [Classical.not_forall, not_imp, not_and, not_or, ne_eq, not_exists, '
                            f'Classical.not_not] at h0; obtain ⟨{", ".join(ws)}, hw⟩ := h0; '
                            f'exact ⟨{", ".join(order)}, by first | grind | simp_all⟩)')
            tactic = 'first\n' + ''.join(f'    | {a}\n' for a in alts) + STEP_TACTIC[len('first\n'):]
        elif consts:
            inst = [f'have i{i}_{j} := h{i} {" ".join([term(c)] * len(_prefix(statement_ast[q])[0]))}'
                    for i, q in enumerate(parents) if statement_ast.get(q) is not None
                    and _prefix(statement_ast[q])[0] and shape.get(q) is None
                    for j, c in enumerate(consts[:3])]
            if inst:
                tactic = STEP_TACTIC + '\n    | (intros; ' + '; '.join(inst) + '; grind)'
        if mine is not None and not new:
            hints = ground_hints([shape.get(q) for q in parents], mine, consts)
            if hints:
                hinted = True
                lines = ([f'intro {" ".join(var(v) for v in mine[0])}'] if mine[0] else []) + \
                        [f'have g{j} := h{i} {" ".join(_render(a) for a in xs)}' for j, (i, xs) in
                         enumerate(hints)] + ['grind']
                tactic = 'first\n    | (' + '; '.join(lines) + ')\n' + tactic[len('first\n'):]
        shape[n] = mine
        statement_ast[n] = f if st['lang'] == 'fof' else None
        lemmas.append(f'theorem {lname} {" ".join(args + hs)} :\n    {concl} := by\n  {tactic}\n')
        call = ' '.join([lname] + binder_names(sig) + [sym(k) for k in used_scope] +
                        [hyp_of.get(q, q) for q in parents])
        if new:
            main.append(f'  obtain ⟨{", ".join(sym(k) for k in new)}, {n}⟩ := {call}')
            for k in new:
                sk_scope[k] = 0
        else:
            main.append(f'  have {n} := {call}')
        hyp_of[n] = n
        statement[n] = prop
        sk_of[n] = sks
        table.append({'name': n, 'role': st['role'], 'rules': st['rules'], 'statuses': st['statuses'],
                      'parents': parents, 'skolems_introduced': new, 'ground_hints': hinted})
    last = steps[-1] if steps else None
    if not last or last['formula'] != ('const', False):
        return None, 'the proof object does not end in the empty clause', table
    head = ' '.join(binders(sig) + [f'(ax{i} : {formula(h)})' for i, h in zip(positions, hyps)])
    text = ('\n'.join(lemmas) + f'\ntheorem {prefix}_thm {head} :\n    {formula(target)} := by\n'
            '  apply Classical.byContradiction\n  intro hgoal\n' + '\n'.join(main) +
            f'\n  exact {last["name"]}\n')
    return text, None, table


def proof_module(problem_id, axioms, goal, proof_text, lemmas=(), goal_deps=None, goal_positions=None):
    """Untrusted: the replay of E's refutation of `goal`, each lemma replayed from its own E
    proof first. `lemmas`: [(formula, proof text)] or [(formula, proof text, deps)], where
    `deps` are the indices of earlier lemmas that were given to E, after the axioms and in
    that order, when the lemma was proved (B20: lemma chains). `goal_deps` likewise for the
    goal; by default every lemma, in order (the B19 form). Returns (module | None, reason,
    tables)."""
    lemmas = [(x[0], x[1], tuple(x[2]) if len(x) > 2 else (), tuple(x[3]) if len(x) > 3 else None) for x in lemmas]
    goal_deps = list(range(len(lemmas))) if goal_deps is None else list(goal_deps)
    sig = signature(list(axioms) + [goal])
    lsig = signature(list(axioms) + [goal] + [l for l, _, _, _ in lemmas])
    if lsig != sig:
        return None, 'a lemma uses a symbol outside the problem signature', {}
    for j, (_, _, deps, _) in enumerate(lemmas):
        if any(not 0 <= d < j for d in deps):
            return None, f'lemma {j} depends on a lemma that is not earlier in the chain', {}
    if any(not 0 <= d < len(lemmas) for d in goal_deps):
        return None, 'the goal depends on an unknown lemma', {}
    stmt, proof = module_names(problem_id)
    blocks, tables = [], {}
    n = len(axioms)
    for j, (lem, text, deps, pos) in enumerate(lemmas):
        block, reason, table = refutation_block(f'L{j}', sig, list(axioms) + [lemmas[d][0] for d in deps], lem, text,
                                                positions=None if pos is None else list(range(n)) + list(pos))
        tables[f'L{j}'] = table
        if block is None:
            return None, f'lemma {j}: {reason}', tables
        blocks.append(block)
    block, reason, table = refutation_block('G', sig, list(axioms) + [lemmas[d][0] for d in goal_deps], goal,
                                            proof_text, positions=None if goal_positions is None else
                                            list(range(n)) + list(goal_positions))
    tables['G'] = table
    if block is None:
        return None, reason, tables
    blocks.append(block)
    names = binder_names(sig)
    axs = [f'ax{i}' for i in range(len(axioms))]
    haves = [f'  have l{j} := L{j}_thm {" ".join(names + axs + [f"l{d}" for d in deps])}'
             for j, (_, _, deps, _) in enumerate(lemmas)]
    source = (f'import {stmt}\n\nset_option maxHeartbeats 400000\n\nnamespace {proof}\n\n' + '\n'.join(blocks) +
              f'\ntheorem proof : {stmt}.stmt := by\n  intro {" ".join(names[:1] + ["hU"] + names[1:] + axs)}\n'
              + ''.join(h + '\n' for h in haves) +
              f'  exact G_thm {" ".join(names + axs + [f"l{d}" for d in goal_deps])}\n\nend {proof}\n')
    return {'name': proof, 'source': source, 'trusted': False}, None, tables


def _checker_cpu_ns(receipt):
    """CPU the checker's sandboxes used (module compiles and the check stage, cgroup-metered); None
    when any part is unmetered or came from the cache without stats (B20R7-OPEN-1)."""
    parts = [0 if m.get('cached') else (m.get('stats') or {}).get('cpu_ns') for m in receipt.get('modules', [])]
    if receipt.get('check_stage') is not None:
        parts.append(receipt['check_stage'].get('cpu_ns'))
    return sum(parts) if parts and all(type(x) is int and x >= 0 for x in parts) else None


def replay(problem_id, axioms, goal, proof_text, *, lemmas=(), goal_deps=None, goal_positions=None, cache=None):
    """Lean replay of an E proof object (and of the E proofs of any lemmas it used).
    Returns a record with status THEOREM_CHECKED (kernel-checked, bound to the trusted
    statement of `axioms → goal`) or NOT_REPLAYED with the reason; the result then stays
    a prover claim."""
    from . import checker
    stmt_mod, spec, sig = statement_module(problem_id, axioms, goal)
    pmod, reason, tables = proof_module(problem_id, axioms, goal, proof_text, lemmas, goal_deps, goal_positions)
    rec = {'problem_id': problem_id, 'statement_module': stmt_mod['name'],
           'statement_sha256': digest({'s': stmt_mod['source']}),
           'steps': sum(len(t) for t in tables.values()), 'lemmas_replayed': len(lemmas),
           'hinted_steps': sum(x['ground_hints'] for t in tables.values() for x in t), 'hints': HINTS}
    if pmod is None:
        return dict(rec, status='NOT_REPLAYED', reason=reason)
    receipt = checker.accept([stmt_mod, pmod], [{'spec': spec, 'proof': f'{pmod["name"]}.proof'}], cache=cache)
    b = receipt['bindings'][0] if receipt.get('bindings') else {'status': receipt.get('status')}
    status = b.get('status')
    out = dict(rec, lean_status=status, outcome=checker.outcome_class(status) if status else None,
               axioms=b.get('axioms'), proof_module_sha256=digest({'s': pmod['source']}),
               cpu_ns=_checker_cpu_ns(receipt))
    if status == 'CHECKED':
        out['status'] = 'THEOREM_CHECKED'
    else:
        mods = {m['name']: m for m in receipt.get('modules', [])}
        pm = mods.get(pmod['name'], {})
        log = pm.get('log') or pm.get('reason') or ''
        errors = [l for l in log.splitlines() if ': error' in l]
        out.update(status='NOT_REPLAYED', reason=f'Lean: {status}', module_result=pm.get('result'),
                   errors=errors[:20])
    return out


# ---------------------------------------------------------------- translation faithfulness

def _table_fn(name, arity, table, size):
    """A Lean function on Fin size given by its full table."""
    if arity == 0:
        return f'({table[()]} : Fin {size})'
    vs = [f'a{i}' for i in range(arity)]
    body = 'fun ' + ' '.join(f'({v} : Fin {size})' for v in vs) + ' => '
    cases = []
    for args, val in sorted(table.items()):
        cond = ' ∧ '.join(f'{v} = {a}' for v, a in zip(vs, args))
        cases.append((cond, val))
    expr = f'({cases[-1][1]} : Fin {size})'
    for cond, val in reversed(cases[:-1]):
        expr = f'(if {cond} then ({val} : Fin {size}) else {expr})'
    return '(' + body + expr + ')'


def truth_table_module(name, items):
    """A trusted module of `decide` checks: items are (formula, Model, expected truth). The
    module compiles iff Lean's evaluation agrees with the expected truth on every item."""
    lines = [f'import Mathlib.Data.Finset.Powerset\n\nnamespace {name}\n']
    for i, (f, model, expected) in enumerate(items):
        sig = signature([f])
        lets = []
        for fn, ar in sorted(sig['functions'].items()):
            lets.append(f'let {sym(fn)} := {_table_fn(fn, ar, model.functions[fn], model.size)}')
        body = formula(f).replace(': U,', f': Fin {model.size},')
        prop = '; '.join(lets + [body]) if lets else body
        claim = prop if expected else f'¬ ({prop})'
        lines.append(f'theorem t{i} : {claim} := by decide\n')
    lines.append(f'end {name}\n')
    return '\n'.join(lines)


